package com.pixilife.android;
import android.app.*;import android.os.*;import android.graphics.Color;import android.provider.Settings;import android.widget.*;import java.io.File;
public class DiagnosticsActivity extends Activity {@Override public void onCreate(Bundle b){super.onCreate(b);TextView t=new TextView(this);t.setPadding(30,30,30,30);t.setTextColor(Color.WHITE);t.setTextSize(17);t.setBackgroundColor(Color.rgb(7,11,17));Runtime r=Runtime.getRuntime();File db=getDatabasePath("pixi_memory.db");t.setText("DIAGNÓSTICO DE PIXI\n\nApp: 2.0\nAndroid: "+Build.VERSION.RELEASE+"\nTeléfono: "+Build.MANUFACTURER+" "+Build.MODEL+"\nMemoria Java libre: "+(r.freeMemory()/1048576)+" MB\nMemoria Java máxima: "+(r.maxMemory()/1048576)+" MB\nBase de memoria: "+(db.exists()?db.length()/1024+" KB":"vacía")+"\nCámara activa: "+(new File(getFilesDir(),"latest_vision.jpg").exists()?"SÍ":"AÚN SIN FOTOGRAMA")+"\nSuperposición: "+(Settings.canDrawOverlays(this)?"CONCEDIDA":"NO CONCEDIDA")+"\nHora: "+new java.util.Date());setContentView(t);}}
